import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-C9Wyh4yY.js";var i=JSON.parse(`{"path":"/vm/esxi/ph48hyup/","title":"ESXi 部署 Debian Cloud 镜像 | ESXi","lang":"zh-CN","frontmatter":{"title":"ESXi 部署 Debian Cloud 镜像","createTime":"2026/08/26 14:46:38","permalink":"/vm/esxi/ph48hyup/"},"readingTime":{"minutes":3.05,"words":916},"git":{},"filePathRelative":"vm/esxi/003.deploying-debian-cloud-image.md","headers":[]}`),a={name:`003.deploying-debian-cloud-image.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>Debian 官方提供预构建的云镜像（Cloud Image），镜像内已集成 cloud-init（云初始化工具），免去手动安装系统的过程。本文记录将 Debian Cloud Image 转换为 ESXi 可用的虚拟磁盘（VMDK，Virtual Machine Disk）、通过 cloud-init 注入初始用户与密码、并在 ESXi 上完成开机与基础配置（SSH、root 密码、网络查看）的完整流程，适用于需要快速在 ESXi 上拉起一台 Debian 虚拟机的场景。</p><h2 id="一、下载-debian-cloud-image" tabindex="-1"><a class="header-anchor" href="#一、下载-debian-cloud-image"><span>一、下载 Debian Cloud Image</span></a></h2><p>官方镜像地址：<a href="https://cloud.debian.org/images/cloud/" target="_blank" rel="noopener noreferrer">https://cloud.debian.org/images/cloud/</a></p><p>下载后假设文件名为 <code>debian.qcow2</code>（qcow2 为 QEMU 的磁盘镜像格式）。</p><h2 id="二、转换为-esxi-可用-vmdk" tabindex="-1"><a class="header-anchor" href="#二、转换为-esxi-可用-vmdk"><span>二、转换为 ESXi 可用 VMDK</span></a></h2><p>先转换成 raw（若原始文件已是 qcow2）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-img</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> convert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qcow2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debian.qcow2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debian.raw</span></span></code></pre></div><p>再转换成 ESXi 可识别的 VMDK：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-img</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> convert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> raw</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vmdk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adapter_type=lsilogic,subformat=monolithicFlat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  debian.raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debian.vmdk</span></span></code></pre></div><div class="hint-container note"><p class="hint-container-title">笔记</p><ul><li><code>adapter_type=lsilogic</code>：指定 SCSI 控制器类型，ESXi 默认可识别。</li><li><code>subformat=monolithicFlat</code>：生成可直接挂载开机的厚置备磁盘，产物为 <code>debian.vmdk</code> 与 <code>debian-flat.vmdk</code> 配对文件。</li></ul></div><div class="hint-container important"><p class="hint-container-title">重要</p><p><code>monolithicFlat</code> 才能直接作为 ESXi 虚拟硬盘开机；<code>streamOptimized</code> 仅用于 OVF/OVA 导入，不能直接挂载启动。</p></div><h2 id="三、创建-cloud-init-配置" tabindex="-1"><a class="header-anchor" href="#三、创建-cloud-init-配置"><span>三、创建 cloud-init 配置</span></a></h2><p>创建 <code>user-data</code>（示例路径 <code>/root/user-data</code>）：</p><div class="language-yaml" data-highlighter="shiki" data-ext="yaml" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-yaml"><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#cloud-config</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">users</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">debian</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sudo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ALL=(ALL) NOPASSWD:ALL</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    lock_passwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">chpasswd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    debian:123456</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  expire</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><div class="hint-container note"><p class="hint-container-title">笔记</p><ul><li><code>lock_passwd</code>: <code>false</code> 允许该用户使用密码登录；</li><li><code>chpasswd</code> : 用户<code>debian</code> ，初始密码 <code>123456</code>；</li></ul></div><p>创建 <code>meta-data</code>（示例路径 <code>/root/meta-data</code>）：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">instance-id: debian-01</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local-hostname: debian</span></span></code></pre></div><h2 id="四、生成-seed-iso" tabindex="-1"><a class="header-anchor" href="#四、生成-seed-iso"><span>四、生成 seed.iso</span></a></h2><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloud-localds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/seed.iso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/user-data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/meta-data</span></span></code></pre></div><div class="hint-container tip"><p class="hint-container-title">提示</p><p><code>cloud-localds</code> 由 <code>cloud-utils</code> 包提供，在 Debian/Ubuntu 主机上执行 <code>apt install cloud-utils</code> 安装。</p></div><div class="hint-container note"><p class="hint-container-title">笔记</p><p>生成成功后得到 <code>/root/seed.iso</code>，该 ISO 在虚拟机首次启动时由 cloud-init 读取，用于初始化用户与主机名。</p></div><h2 id="五、在-esxi-创建虚拟机" tabindex="-1"><a class="header-anchor" href="#五、在-esxi-创建虚拟机"><span>五、在 ESXi 创建虚拟机</span></a></h2><ol><li>创建新虚拟机： <ul><li>客户机操作系统：Linux → Debian 13（64 位）</li><li>SCSI 控制器：LSI Logic SAS</li></ul></li><li>上传 <code>debian.vmdk</code> 到 datastore</li><li>上传 <code>seed.iso</code> 到 datastore</li><li>编辑虚拟机设置： <ul><li>将 <code>debian.vmdk</code> 添加为硬盘</li><li>将 <code>seed.iso</code> 挂载到 CD/DVD 驱动器</li></ul></li><li>确保 CD/DVD 驱动器「开机时连接」已勾选（首次启动必须能读到 seed.iso）</li></ol><h2 id="六、启动虚拟机" tabindex="-1"><a class="header-anchor" href="#六、启动虚拟机"><span>六、启动虚拟机</span></a></h2><p>首次启动时，cloud-init 读取 <code>seed.iso</code>，自动创建用户 <code>debian</code>，密码 <code>123456</code>。</p><p>登录信息：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>用户名：debian</span></span>
<span class="line"><span>密码：123456</span></span></code></pre></div><p>验证 sudo 权限：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span></span></code></pre></div><h2 id="七、清理-可选" tabindex="-1"><a class="header-anchor" href="#七、清理-可选"><span>七、清理（可选）</span></a></h2><ul><li>首次启动并登录后，可在虚拟机设置中卸载 <code>seed.iso</code></li><li>删除 <code>/root/seed.iso</code>，避免下次开机 cloud-init 重复应用初始化配置</li><li>按需修改用户密码或创建更多用户</li></ul><h2 id="八、开启-ssh-登录" tabindex="-1"><a class="header-anchor" href="#八、开启-ssh-登录"><span>八、开启 SSH 登录</span></a></h2><ol><li><p>备份原配置文件：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.bak</span></span></code></pre></div></li><li><p>编辑 SSH 配置文件：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span></span></code></pre></div></li><li><p>找到并修改以下参数（行首 <code>#</code> 注释符需一并删除）：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PermitRootLogin yes</span></span></code></pre></div><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PasswordAuthentication yes</span></span></code></pre></div></li><li><p>保存并退出（Nano：<kbd>Ctrl</kbd>+<kbd>O</kbd> 保存，<kbd>Ctrl</kbd>+<kbd>X</kbd> 退出）。</p></li><li><p>重启 SSH 服务：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div></li></ol><div class="hint-container warning"><p class="hint-container-title">警告</p><p>开启 <code>PermitRootLogin yes</code> 且使用密码认证属于高危配置，仅建议在隔离的内网环境或临时调试时使用；生产环境应改用密钥登录并禁用 root 远程登录。</p></div><h2 id="九、其他配置" tabindex="-1"><a class="header-anchor" href="#九、其他配置"><span>九、其他配置</span></a></h2><ol><li><p>为 root 用户设定密码：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span></span></code></pre></div></li><li><p>查看当前网络接口：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span></span></code></pre></div></li></ol><h2 id="十、vmdk-子格式对比" tabindex="-1"><a class="header-anchor" href="#十、vmdk-子格式对比"><span>十、VMDK 子格式对比</span></a></h2><table><thead><tr><th>子格式（subformat）</th><th>用途</th><th>能否直接开机</th></tr></thead><tbody><tr><td>monolithicFlat</td><td>ESXi 虚拟硬盘（厚置备）</td><td>能</td></tr><tr><td>thin</td><td>ESXi 虚拟硬盘（精简置备）</td><td>能</td></tr><tr><td>streamOptimized</td><td>OVF/OVA 导出导入</td><td>不能（仅用于导入）</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>直接在 ESXi 上开机，选 <code>monolithicFlat</code>（厚置备）或 <code>thin</code>（精简置备）；需要打包成 OVA 分发时才用 <code>streamOptimized</code>。</p></div>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};